/*==================[macros]=================================================*/

/* configuration signature access macros */
/* macro checks matching byte-order between BSW and configuration signature */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Check_Endianess(signature) \
  (((signature) & SP_UINT32_C(0x80808080)) == SP_UINT32_C(0x80000000))

/* macro fetches the alignment information out of the signature */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Get_Alignment(signature) \
  (SP_UINT32_C(0x00000003) & (signature))

/* alignment value definitions */
#define TS_SIG_ALIGNMENT_1_1_1 SP_UINT32_C(0x0)
#define TS_SIG_ALIGNMENT_1_2_2 SP_UINT32_C(0x1)
#define TS_SIG_ALIGNMENT_1_2_4 SP_UINT32_C(0x2)

/* get module ID from signature*/
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Get_Module_Id(signature) \
  (((signature) & SP_UINT32_C(0x00007F00)) >> SP_UINT32_C(8))

/* get configuration interface variant identifier out of signature */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Get_Mcg_Ifver_Variant(signature) \
  (((signature) & SP_UINT32_C(0x0000007C)) >> SP_UINT32_C(2))

/* get required BSW interface identifier out of signature */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Get_Mcg_Bsw_Ifversion_Required(signature) \
  (((signature) & SP_UINT32_C(0xFFFF0000)) >> SP_UINT32_C(16))

/* get provided configuration interface identifier out of signature */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Get_Mcg_Bsw_Ifversion_Provided(signature) \
    ((signature) & SP_UINT32_C(0x0000FFFF))

/* get switch setting out of signature: RELOCATABLE_CFG_ENABLE */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Cfg_On_Relocatable_Cfg_Enable(signature) \
  ((SP_UINT32_C(0x00010000) & (signature)) != SP_UINT32_C(0))

/* get switch setting out of signature: CFG_ALIGNMENT_ENABLE */
/* MISRA-1 */ /* PRQA S 3453 2 */ /* macros used like functions. */
#define TS_Sig_Cfg_On_Cfg_Alignment_Enable(signature) \
  ((SP_UINT32_C(0x00020000) & (signature)) != SP_UINT32_C(0))

/* Get the byte offset of a structure member */
/* MISRA-1 */ /* PRQA S 3410,3453 3 */ /* Since using a macro argument against type, can not  add the parentheses. */
#define TS_OffsetOf(structure, member) \
    ((uint32) &(((structure *) 0)->member))


/* Get alignment of type within structures */
/* MISRA-1 */ /* PRQA S 3410 3 */ /* Since using a macro argument against type, can not  add the parentheses. */
/* MISRA-1 */ /* PRQA S 3412 2 */ /* Macro is used to keep the code readable. */
#define TS_AlignOf(type) \
    TS_OffsetOf(struct {uint8 nMember1; type nMember2;}, nMember2)

/* MISRA-1 */ /* PRQA S 3412 6 */ /* Macro is used to keep the code readable. */
#define TS_Additional_Padding_Bytes_Inserted()             \
    (                                                   \
        (sizeof(struct {uint8 nMember;}) != 1U) ||       \
        (sizeof(struct {uint16 nMember;}) != 2U) ||      \
        (sizeof(struct {uint32 nMember;}) != 4U)         \
    )

